#Requires -Version 5.1
# fix-android-upload-pdf-v2.ps1
# Fix 1 (Android galeria): input type=file sin "multiple" y con accept
#   con extensiones explicitas — Chrome Android con accept="image/*" solo
#   muestra la camara; las extensiones explicitas muestran la galeria tambien.
# Fix 2 (Build): sharp importado con try/catch en lugar de cast de tipos
#   que causaba error TS2307 en el build de Vercel.
# Fix 3 (PDF): compresion con sharp protegida por null-check por si no
#   esta disponible en el entorno de ejecucion.

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Aplicando fixes Android + PDF + build" -ForegroundColor Cyan

Write-Host "  -> src\app\partes\[id]\page.tsx" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\partes\[id]\page.tsx"), $bytes)
Write-Host "  OK: 25 KB" -ForegroundColor Green

Write-Host "  -> src\lib\pdf\generatePartePdf.ts" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\lib\pdf\generatePartePdf.ts"), $bytes)
Write-Host "  OK: 11 KB" -ForegroundColor Green

Write-Host "  -> src\app\api\partes\email\route.ts" -ForegroundColor Gray
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\api\partes\email\route.ts"), $bytes)
Write-Host "  OK: 7 KB" -ForegroundColor Green

Write-Host ""
Write-Host "  Verificando..." -ForegroundColor Cyan
$page = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\partes\[id]\page.tsx"), [System.Text.Encoding]::UTF8)
$pdf  = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\lib\pdf\generatePartePdf.ts"), [System.Text.Encoding]::UTF8)
if ($page.Contains('.jpg,.jpeg,.png'))  { Write-Host "  OK: accept con extensiones (Android galeria)" -ForegroundColor Green } else { Write-Host "  ERROR accept" -ForegroundColor Red }
if (-not $page.Contains('multiple'))    { Write-Host "  OK: sin multiple" -ForegroundColor Green } else { Write-Host "  WARN: queda multiple" -ForegroundColor Yellow }
if ($pdf.Contains('try { sharp = require')) { Write-Host "  OK: sharp con try/catch (build seguro)" -ForegroundColor Green } else { Write-Host "  ERROR sharp" -ForegroundColor Red }
Write-Host ""
Write-Host '  git add "src\app\partes\[id]\page.tsx" src\lib\pdf\generatePartePdf.ts src\app\api\partes\email\route.ts'
Write-Host '  git commit -m "fix: Android galeria + build sharp + compresion PDF"'
Write-Host '  git push'
